from flask import Flask, render_template, requestimport osapp = Flask(__name__)@app.route("/")def index():    return render_template("index.html")from flask import request, redirect, flashimport smtplibfrom email.mime.text import MIMETextfrom flask import request, jsonifyimport smtplibfrom email.mime.text import MIMEText@app.route('/contact-sponsor', methods=['POST'])def contact_sponsor():    choix = request.form.get('choix')    email = request.form.get('email')    # sécurité basique    if not choix or not email:        return jsonify({"status": "error", "message": "Données manquantes"})    message = f"""Nouvelle demande sponsor :Choix : {choix}Email : {email}"""    msg = MIMEText(message)    msg['Subject'] = "Nouveau contact sponsor"    msg['From'] = "lasyzygie4L@gmail.com"    msg['To'] = "lasyzygie4L@gmail.com"    try:        server = smtplib.SMTP_SSL('smtp.gmail.com', 465)        server.login(            os.environ.get("EMAIL_USER"),            os.environ.get("EMAIL_PASS")            )        server.send_message(msg)        server.quit()        return jsonify({"status": "ok"})    except Exception as e:        print(e)        return jsonify({"status": "error"})@app.route("/equipage")def equipage():    return render_template("equipe.html")@app.route("/concept")def concept():    return render_template("concept.html")@app.route("/pourquoi")def pourquoi():    return render_template("pourquoi.html")@app.route("/financer")def financer():    return render_template("financer.html")if __name__ == "__main__":    app.run(debug=True)    